mapper.select:
SELECT id, portal_id AS portalId, gmt_create AS gmtCreate, gmt_modify AS gmtModify, file_name AS fileName, file_path AS filePath, file_size AS fileSize, file_type AS fileType, file_ext AS fileExt, stage, attachment_state AS attachmentState, ai_text AS aiText FROM b_portal_attachment WHERE 1 = 1
AND id = #{id}
AND portal_id = #{portalId}
AND attachment_state = #{attachmentState}
AND stage = #{stage}
AND file_path = #{filePath}
AND file_name LIKE CONCAT('%', #{fileName}, '%')
ORDER BY gmt_create ASC, id ASC LIMIT #{offset}, #{rows};

